def arm(x0,y0,n):
    return ('<path d="M%d %d q60 -30 120 0 l0 40 q-60 30 -120 0 Z" fill="#ffe0d6" stroke="#8d6e63" stroke-width="2"/>'%(x0,y0)+
            '<rect x="%d" y="%d" width="24" height="46" rx="4" fill="#c8e6c9" stroke="#2e7d32"/>'%(x0+48,y0-4)+
            ('<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="#5d4037" stroke-width="6"/>'%(x0+30,y0-26,x0+100,y0+40) if n>=2 else '')+
            T(x0+10,y0-18,str(n),16,'start',700))
